from docx import Document
import sys

def check_document():
    doc = Document('/root/offer_letter_filled.docx')
    full_text = []
    for para in doc.paragraphs:
        full_text.append(para.text)
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    full_text.append(para.text)

    content = '\n'.join(full_text)

    # Check for remaining placeholders
    if '{{' in content or '}}' in content:
        print("FAILED: Found remaining placeholders {{...}}")
        # Print a snippet to see what remains
        start = content.find('{{')
        print(f"Snippet: {content[start:start+50]}")
        sys.exit(1)

    # Check for relocation markers
    if 'IF_RELOCATION' in content:
        print("FAILED: Found relocation markers")
        sys.exit(1)

    # Check for relocation data (since it was Yes)
    # We know the amount is 15,000 from the json
    if '15,000' not in content:
        print("WARNING: Did not find relocation amount 15,000 in text")

    print("VERIFICATION SUCCESS: No placeholders found, markers removed.")

if __name__ == "__main__":
    check_document()
